function ensureStylesInjected(): void {
  if (typeof document === 'undefined') {
    return;
  }
  if (document.getElementById(STYLE_ELEMENT_ID)) {
    return;
  }
  const styleEl = document.createElement('style');
  styleEl.id = STYLE_ELEMENT_ID;
  styleEl.textContent = CSS_TEXT;
  document.head.appendChild(styleEl);
}

function classNames(...values: Array<string | false | null | undefined>): string {
  return values.filter(Boolean).join(' ');
}

function resolveIndicator(status: StepStatus): { icon: ReactNode; className: string } {
  switch (status) {
    case 'complete':
      return {
        icon: <CheckCircleIcon className="cot-indicator-icon" />,
        className: 'cot-indicator-complete',
      };
    case 'active':
      return {
        icon: <ActiveRingIcon className="cot-indicator-icon" />,
        className: 'cot-indicator-active',
      };
    case 'pending':
    default:
      return {
        icon: <PendingCircleIcon className="cot-indicator-icon" />,
        className: 'cot-indicator-pending',
      };
  }
}

function summarizeProgress(steps: ReasoningStep[]): string {
  const total = steps.length;
  if (total === 0) {
    return 'No steps';
  }
  const complete = steps.filter((s) => (s.status ?? 'pending') === 'complete').length;
  const active = steps.filter((s) => (s.status ?? 'pending') === 'active').length;
  const parts = [`${complete} of ${total} complete`];
  if (active > 0) {
    parts.push(`${active} in progress`);
  }
  return parts.join(' \u00b7 ');
}

export function ChainOfThoughtSearchResults({
  results,
  className,
}: ChainOfThoughtSearchResultsProps) {
  if (results.length === 0) {
    return null;
  }
  return (
    <div className={classNames('cot-search-section', className)}>
      <span className="cot-search-heading">
        <SearchIcon className="cot-search-heading-icon" />
        {results.length === 1 ? '1 source' : `${results.length} sources`}
      </span>
      <div className="cot-badges">
        {results.map((result) =>
          result.url ? (

              <span className="cot-badge-label">{result.label}</span>
              <ExternalLinkIcon className="cot-badge-external-icon" />

          ) : (
            <span key={result.id} className="cot-badge" title={result.label}>
              <span className="cot-badge-label">{result.label}</span>
            </span>
          ),
        )}
      </div>
    </div>
  );
}

export function ChainOfThoughtImage({
  src,
  alt,
  caption,
  className,
}: ChainOfThoughtImageProps) {
  return (
    <figure className={classNames('cot-figure', className)}>
      <img className="cot-image" src={src} alt={alt} loading="lazy" />
      {caption ? <figcaption className="cot-caption">{caption}</figcaption> : null}
    </figure>
  );
}

export function ChainOfThoughtStep({
  label,
  description,
  status = 'pending',
  icon,
  isLast = false,
  className,
  children,
}: ChainOfThoughtStepProps) {
  const indicator = resolveIndicator(status);
  const labelClass = classNames(
    'cot-step-label',
    status === 'pending' && 'cot-step-label-pending',
  );
  return (
    <li className={classNames('cot-step', isLast && 'cot-step-last', className)}>
      <span className="cot-connector" aria-hidden="true" />
      <span className={classNames('cot-indicator', indicator.className)} aria-hidden="true">
        {icon ?? indicator.icon}
      </span>
      <div className="cot-step-body">
        <div className={labelClass}>{label}</div>
        {description ? <p className="cot-step-description">{description}</p> : null}
        {children ? <div className="cot-step-extras">{children}</div> : null}
      </div>
    </li>
  );
}

export function ChainOfThought({
  steps,
  title = 'Reasoning',
  defaultOpen = false,
  open,
  onOpenChange,
  className,
  appearance = 'dark',
  children,
}: ChainOfThoughtProps) {
  ensureStylesInjected();
  const [internalOpen, setInternalOpen] = useState<boolean>(defaultOpen);
  const isControlled = open !== undefined;
  const isOpen = isControlled ? (open as boolean) : internalOpen;
  const reactId = useId();
  const regionId = `cot-region-${reactId}`;
  const headerId = `cot-header-${reactId}`;

  const toggle = useCallback(() => {
    const next = !isOpen;
    if (!isControlled) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  }, [isControlled, isOpen, onOpenChange]);

  const subtitle = useMemo(() => {
    if (steps && steps.length > 0) {
      return summarizeProgress(steps);
    }
    return isOpen ? 'Hide reasoning' : 'Show reasoning';
  }, [steps, isOpen]);

  return (
    <section
      className={classNames('cot-root', className)}
      data-appearance={appearance}
    >
      <button
        type="button"
        id={headerId}
        className="cot-header"
        aria-expanded={isOpen}
        aria-controls={regionId}
        onClick={toggle}
      >
        <span className="cot-header-icon-wrap" aria-hidden="true">
          <SparkleIcon className="cot-header-icon" />
        </span>
        <span className="cot-header-text">
          <span className="cot-title">{title}</span>
          <span className="cot-subtitle">{subtitle}</span>
